// The smallest worker that proves the file list: install caches SHELL (generated by tools/sw-files.mjs, never edited
// by hand), then every request is answered from the cache first.
const CACHE = 'outside-package-v1';
const SHELL = [
  './',
  'plain.html',
  'src/check-zod.js',
  'src/plain.js',
  'src/register-sw.js',
  'src/show.js',
  'vendor/zod/3.23.8/LICENSE',
  'vendor/zod/3.23.8/index.mjs',
];

self.addEventListener('install', e => e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting())));
self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));
self.addEventListener('fetch', e => e.respondWith(caches.match(e.request).then(hit => hit || fetch(e.request))));
